import React from "react";
import {
  FaChevronLeft,
  FaPaperPlane,
  FaMicrophone,
  FaStop,
  FaTrash,
  FaPlay,
} from "react-icons/fa";
import { apiGet, apiPost } from "../common/api";
import Loader from "../common/Loader";
import withRouter from "../common/withRouter";

class ChatSupportPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      messages: [],
      text: "",
      loading: true,
      sending: false,
      recording: false,
      audioUrl: null,
      recordingTime: 0,
    };

    this.mediaRecorder = null;
    this.audioChunks = [];
    this.audioStream = null;
    this.timer = null;

    this.handleBack = this.handleBack.bind(this);
    this.handleTextChange = this.handleTextChange.bind(this);
    this.handleSend = this.handleSend.bind(this);
    this.startRecording = this.startRecording.bind(this);
    this.stopRecording = this.stopRecording.bind(this);
    this.cancelRecording = this.cancelRecording.bind(this);
    this.sendVoice = this.sendVoice.bind(this);
  }

  componentDidMount() {
    this.loadMessages();
  }

  componentWillUnmount() {
    this.stopTimer();

    if (this.audioStream) {
      this.audioStream.getTracks().forEach((track) => track.stop());
    }

    if (this.state.audioUrl) {
      URL.revokeObjectURL(this.state.audioUrl);
    }
  }

  loadMessages() {
    apiGet("/messages")
      .then((json) => {
        this.setState({
          messages: json.messages || [],
          loading: false,
        });
      })
      .catch(() => {
        this.setState({
          loading: false,
        });
      });
  }

  handleBack() {
    this.props.navigate(-1);
  }

  handleTextChange(e) {
    this.setState({
      text: e.target.value,
    });
  }

  handleSend(e) {
    e.preventDefault();

    const { text } = this.state;

    if (!text.trim()) {
      return;
    }

    this.setState({
      sending: true,
    });

    apiPost("/messages", {
      text: text.trim(),
    })
      .then(() => {
        this.setState({
          sending: false,
          text: "",
        });

        this.loadMessages();
      })
      .catch(() => {
        this.setState({
          sending: false,
        });
      });
  }

  async startRecording() {
    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        alert("مرورگر شما از ضبط صدا پشتیبانی نمی‌کند.");
        return;
      }

      const stream = await navigator.mediaDevices.getUserMedia({
        audio: true,
      });

      this.audioStream = stream;
      this.audioChunks = [];

      let mimeType = "audio/webm";

      if (!MediaRecorder.isTypeSupported("audio/webm")) {
        if (MediaRecorder.isTypeSupported("audio/mp4")) {
          mimeType = "audio/mp4";
        } else if (MediaRecorder.isTypeSupported("audio/ogg")) {
          mimeType = "audio/ogg";
        } else {
          mimeType = "";
        }
      }

      this.mediaRecorder = mimeType
        ? new MediaRecorder(stream, { mimeType })
        : new MediaRecorder(stream);

      this.mediaRecorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) {
          this.audioChunks.push(event.data);
        }
      };

      this.mediaRecorder.onstop = () => {
        const actualMimeType =
          this.mediaRecorder.mimeType || mimeType || "audio/webm";

        const audioBlob = new Blob(this.audioChunks, {
          type: actualMimeType,
        });

        const audioUrl = URL.createObjectURL(audioBlob);

        this.audioBlob = audioBlob;

        this.setState({
          recording: false,
          audioUrl,
          recordingTime: 0,
        });

        if (this.audioStream) {
          this.audioStream.getTracks().forEach((track) => track.stop());
          this.audioStream = null;
        }

        this.stopTimer();
      };

      this.mediaRecorder.start();

      this.setState({
        recording: true,
        recordingTime: 0,
        audioUrl: null,
      });

      this.startTimer();
    } catch (error) {
      console.error(error);

      alert(
        "دسترسی به میکروفون داده نشد. لطفاً اجازه استفاده از میکروفون را فعال کنید."
      );
    }
  }

  stopRecording() {
    if (
      this.mediaRecorder &&
      this.mediaRecorder.state !== "inactive"
    ) {
      this.mediaRecorder.stop();
    }
  }

  cancelRecording() {
    if (
      this.mediaRecorder &&
      this.mediaRecorder.state !== "inactive"
    ) {
      this.mediaRecorder.ondataavailable = null;
      this.mediaRecorder.onstop = null;
      this.mediaRecorder.stop();
    }

    if (this.audioStream) {
      this.audioStream.getTracks().forEach((track) => track.stop());
      this.audioStream = null;
    }

    this.stopTimer();

    if (this.state.audioUrl) {
      URL.revokeObjectURL(this.state.audioUrl);
    }

    this.audioChunks = [];
    this.audioBlob = null;

    this.setState({
      recording: false,
      audioUrl: null,
      recordingTime: 0,
    });
  }

  startTimer() {
    this.stopTimer();

    this.timer = setInterval(() => {
      this.setState((prevState) => ({
        recordingTime: prevState.recordingTime + 1,
      }));
    }, 1000);
  }

  stopTimer() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  formatTime(seconds) {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;

    return `${String(minutes).padStart(2, "0")}:${String(
      remainingSeconds
    ).padStart(2, "0")}`;
  }

  async sendVoice() {
    if (!this.audioBlob) {
      return;
    }

    this.setState({
      sending: true,
    });

    try {
      const formData = new FormData();

      let extension = "webm";

      if (this.audioBlob.type.includes("mp4")) {
        extension = "mp4";
      } else if (this.audioBlob.type.includes("ogg")) {
        extension = "ogg";
      }

      formData.append(
        "file",
        this.audioBlob,
        `voice_${Date.now()}.${extension}`
      );

      /*
       * این همان endpoint فعلی messagesPost است.
       * هیچ تغییری در بک‌اند لازم نیست.
       */
      await apiPost("/messages", formData);

      if (this.state.audioUrl) {
        URL.revokeObjectURL(this.state.audioUrl);
      }

      this.audioBlob = null;

      this.setState({
        sending: false,
        audioUrl: null,
        recordingTime: 0,
      });

      this.loadMessages();
    } catch (error) {
      console.error(error);

      this.setState({
        sending: false,
      });

      alert("ارسال ویس انجام نشد.");
    }
  }

  getFileUrl(file) {
    if (!file) {
      return "";
    }

    if (file.startsWith("http://") || file.startsWith("https://")) {
      return file;
    }

    /*
     * فایل‌های چت توسط Laravel در files/chats ذخیره می‌شوند.
     *
     * اگر API شما روی همان دامنه است، این قسمت درست کار می‌کند.
     */
    return `${window.location.origin}/test/files/chats${file}`;
  }

  renderMessage(message) {
    const hasFile = !!message.file;
    const hasText = !!message.text;

    return (
      <div key={message.id} className="mb-3 text-end">
        <div
          className="d-inline-flex flex-column align-items-end bg-light rounded-3 px-3 py-2"
          style={{ maxWidth: "85%" }}
        >
          {hasFile && (
            <div className="mb-1 w-100">
              <audio
                controls
                preload="metadata"
                src={this.getFileUrl(message.file)}
                style={{
                  width: 240,
                  maxWidth: "100%",
                }}
              />
            </div>
          )}

          {hasText && (
            <div className="text-dark">
              {message.text}
            </div>
          )}
        </div>
      </div>
    );
  }

  render() {
    const {
      messages,
      text,
      loading,
      sending,
      recording,
      audioUrl,
      recordingTime,
    } = this.state;

    return (
      <div
        dir="rtl"
        lang="fa"
        className="bg-white min-vh-100 d-flex flex-column"
      >
        {loading && <Loader />}

        {/* Header */}
        <div
          className="d-flex align-items-center justify-content-between px-3 pt-4 pb-3 border-bottom"
          style={{
            maxWidth: 480,
            margin: "0 auto",
            width: "100%",
          }}
        >
          <button
            type="button"
            onClick={this.handleBack}
            className="btn btn-light rounded-circle border p-2 d-flex align-items-center justify-content-center"
            style={{
              width: 36,
              height: 36,
            }}
          >
            <FaChevronLeft size={14} />
          </button>

          <h1 className="fs-6 fw-semibold text-dark m-0">
            پشتیبانی
          </h1>

          <div style={{ width: 36 }} />
        </div>

        {/* Messages */}
        <div
          className="flex-grow-1 px-3 py-3 overflow-auto"
          style={{
            maxWidth: 480,
            margin: "0 auto",
            width: "100%",
          }}
        >
          {messages.length === 0 && !loading ? (
            <div className="text-center text-muted py-5">
              هنوز پیامی وجود ندارد.
            </div>
          ) : (
            messages.map((message) =>
              this.renderMessage(message)
            )
          )}
        </div>

        {/* Recording preview */}
        {audioUrl && !recording && (
          <div
            className="px-3 pb-2"
            style={{
              maxWidth: 480,
              margin: "0 auto",
              width: "100%",
            }}
          >
            <div className="border rounded-4 p-2 d-flex align-items-center gap-2">
              <audio
                controls
                src={audioUrl}
                style={{
                  flex: 1,
                  minWidth: 0,
                }}
              />

              <button
                type="button"
                onClick={this.cancelRecording}
                disabled={sending}
                className="btn btn-light text-danger rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaTrash size={14} />
              </button>

              <button
                type="button"
                onClick={this.sendVoice}
                disabled={sending}
                className="btn btn-primary rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaPaperPlane size={14} />
              </button>
            </div>
          </div>
        )}

        {/* Input */}
        {!recording && !audioUrl && (
          <form
            onSubmit={this.handleSend}
            className="d-flex align-items-center gap-2 px-3 py-3 border-top"
            style={{
              maxWidth: 480,
              margin: "0 auto",
              width: "100%",
            }}
          >
            <button
              type="button"
              onClick={this.startRecording}
              disabled={sending}
              className="btn btn-light border rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 40,
                height: 40,
                flexShrink: 0,
              }}
            >
              <FaMicrophone size={16} />
            </button>

            <input
              type="text"
              placeholder="پیام خود را بنویسید..."
              value={text}
              onChange={this.handleTextChange}
              className="form-control border rounded-pill text-end px-3 py-2"
            />

            <button
              type="submit"
              disabled={sending || !text.trim()}
              className="btn btn-primary rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 40,
                height: 40,
                flexShrink: 0,
              }}
            >
              <FaPaperPlane size={14} />
            </button>
          </form>
        )}

        {/* Recording */}
        {recording && (
          <div
            className="px-3 py-3 border-top"
            style={{
              maxWidth: 480,
              margin: "0 auto",
              width: "100%",
            }}
          >
            <div className="d-flex align-items-center gap-2">
              <button
                type="button"
                onClick={this.cancelRecording}
                className="btn btn-light text-danger border rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaTrash size={14} />
              </button>

              <div
                className="flex-grow-1 bg-light rounded-pill px-3 py-2 d-flex align-items-center justify-content-between"
              >
                <span className="text-danger fw-semibold">
                  ● در حال ضبط
                </span>

                <span className="text-dark">
                  {this.formatTime(recordingTime)}
                </span>
              </div>

              <button
                type="button"
                onClick={this.stopRecording}
                className="btn btn-danger rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaStop size={14} />
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }
}

export default withRouter(ChatSupportPage);
